#!/usr/bin/env python3
"""
Migration script: convert short names (e.g. "single-line", "primary-surface")
to canonical UDIs where a mapping exists, and bump canonical schema versions
by patch +0.0.1. Backups are written with a .bak suffix. Writes a migration
log into .workspace/.artifacts/.checklists/migration.log and adds checklist
entries for any unresolved tokens.

Run from repository root.
"""
from __future__ import annotations

import sys
from pathlib import Path
import yaml
import shutil
import re
from typing import Dict, Any, Tuple
import argparse

REPO = Path(__file__).resolve().parents[3]
ROOT = REPO
META = ROOT / "Meta"

SCHEMA_DIR = META / "canonical" / "object.schemas"
REGISTRY_ROOT = META / "registry"

TARGET_KEYS = {"colour_role", "colour_scheme", "border_pattern", "content_role", "ui_framework", "capability"}


def load_registries() -> Dict[str, Dict[str, Any]]:
    regs: Dict[str, Dict[str, Any]] = {}
    # border-patterns
    bp_dir = REGISTRY_ROOT / "border-pattern.d"
    if bp_dir.exists():
        for f in bp_dir.glob("*.yaml"):
            try:
                d = yaml.safe_load(f.read_text(encoding='utf-8'))
            except Exception:
                continue
            if isinstance(d, dict):
                udi = d.get('udi')
                idv = d.get('id')
                if isinstance(idv, str):
                    regs.setdefault('border_patterns', {})[idv] = d
                if isinstance(udi, str):
                    regs.setdefault('border_patterns', {})[udi] = d
    # colour-roles
    cr_dir = REGISTRY_ROOT / "colour-role.d"
    if cr_dir.exists():
        for f in cr_dir.glob("*.yaml"):
            try:
                d = yaml.safe_load(f.read_text(encoding='utf-8'))
            except Exception:
                continue
            if isinstance(d, dict):
                udi = d.get('udi')
                idv = d.get('id')
                if isinstance(idv, str):
                    regs.setdefault('colour_roles', {})[idv] = d
                if isinstance(udi, str):
                    regs.setdefault('colour_roles', {})[udi] = d
    # colour-schemes
    cs_dir = REGISTRY_ROOT / "colour-scheme.d"
    if cs_dir.exists():
        for f in cs_dir.glob("*.yaml"):
            try:
                d = yaml.safe_load(f.read_text(encoding='utf-8'))
            except Exception:
                continue
            if isinstance(d, dict):
                udi = d.get('udi')
                idv = d.get('id')
                if isinstance(idv, str):
                    regs.setdefault('colour_schemes', {})[idv] = d
                if isinstance(udi, str):
                    regs.setdefault('colour_schemes', {})[udi] = d
    # ui-frameworks
    uf_dir = REGISTRY_ROOT / "ui-framework.d"
    if uf_dir.exists():
        for f in uf_dir.glob("*.yaml"):
            try:
                d = yaml.safe_load(f.read_text(encoding='utf-8'))
            except Exception:
                continue
            if isinstance(d, dict):
                udi = d.get('udi')
                idv = d.get('id')
                if isinstance(idv, str):
                    regs.setdefault('ui_frameworks', {})[idv] = d
                if isinstance(udi, str):
                    regs.setdefault('ui_frameworks', {})[udi] = d

    return regs


def bump_version(v: str) -> str:
    parts = [int(p) for p in re.findall(r"\d+", v)]
    if len(parts) >= 3:
        parts[2] += 1
        return f"{parts[0]}.{parts[1]}.{parts[2]}"
    if len(parts) == 2:
        return f"{parts[0]}.{parts[1]}.1"
    return v


def process_value(val: Any, regs: Dict[str, Dict[str, Any]], unresolved: list) -> Any:
    if not isinstance(val, str):
        return val
    token = val.strip()
    if not token:
        return val
    # prefer direct UDI
    if token.startswith('prismata.'):
        return token
    # search registries
    for reg in regs.values():
        if token in reg:
            entry = reg[token]
            udi = entry.get('udi')
            if isinstance(udi, str):
                return udi
        low = token.lower()
        if low in reg:
            entry = reg[low]
            udi = entry.get('udi')
            if isinstance(udi, str):
                return udi
        # tail search
        for entry in reg.values():
            if not isinstance(entry, dict):
                continue
            udi = entry.get('udi')
            if isinstance(udi, str) and udi.strip().endswith(token):
                return udi

    unresolved.append(token)
    return val


def recursive_patch(obj: Any, regs: Dict[str, Dict[str, Any]], unresolved: list) -> Any:
    if isinstance(obj, dict):
        changed = False
        out = {}
        for k, v in obj.items():
            if k in TARGET_KEYS:
                newv = process_value(v, regs, unresolved)
                out[k] = newv
                if newv != v:
                    changed = True
            else:
                out[k] = recursive_patch(v, regs, unresolved)
                if out[k] != v:
                    changed = True
        return out
    if isinstance(obj, list):
        return [recursive_patch(i, regs, unresolved) for i in obj]
    return obj


def main(dry_run: bool = False):
    regs = load_registries()
    # Bump canonical schema versions
    schema_versions: Dict[str, str] = {}
    for sfile in SCHEMA_DIR.glob("*.schema.yaml"):
        try:
            data = yaml.safe_load(sfile.read_text(encoding='utf-8')) or {}
        except Exception:
            continue
        sv = data.get('schema_version')
        if isinstance(sv, str):
            newv = bump_version(sv)
            data['schema_version'] = newv
            schema_versions[sfile.name] = newv
            if not dry_run:
                sfile.write_text(yaml.safe_dump(data, sort_keys=False), encoding='utf-8')

    # Walk all yaml files
    unresolved_tokens: list[str] = []
    planned_changes: list[tuple[Path, Any, Any]] = []
    for y in ROOT.rglob('*.yaml'):
        try:
            raw = y.read_text(encoding='utf-8')
        except Exception:
            continue
        try:
            data = yaml.safe_load(raw)
        except Exception:
            continue
        if data is None:
            continue
        newdata = recursive_patch(data, regs, unresolved_tokens)
        if newdata != data:
            # record planned change
            planned_changes.append((y, data, newdata))
            if not dry_run:
                # backup
                bak = y.with_suffix(y.suffix + '.bak')
                if not bak.exists():
                    shutil.copy2(y, bak)
                y.write_text(yaml.safe_dump(newdata, sort_keys=False), encoding='utf-8')
            # update registry entry schema_version if this file is in registry
            try:
                rel = y.relative_to(META / 'registry')
                # pick canonical schema for kind from file name pattern
                # determine kind from path parts
                kind = rel.parts[0] if rel.parts else None
                # map registry folder to canonical schema file
                mapping = {
                    'border-pattern.d': 'border-pattern.schema.yaml',
                    'colour-role.d': 'colour-role.schema.yaml',
                    'colour-scheme.d': 'colour-scheme.schema.yaml',
                    'ui-framework.d': 'ui-framework.schema.yaml',
                    'menu.d': 'menu.schema.yaml',
                    'menu-item.d': 'menu-item.schema.yaml',
                    'pane.d': 'pane.schema.yaml',
                }
                folder = rel.parts[0]
                schema_file = mapping.get(folder)
                if schema_file and schema_file in schema_versions:
                    # set schema_version in the updated file
                    d2 = yaml.safe_load(y.read_text(encoding='utf-8')) or {}
                    d2['schema_version'] = schema_versions[schema_file]
                    y.write_text(yaml.safe_dump(d2, sort_keys=False), encoding='utf-8')
            except Exception:
                pass

    # Write migration log and unresolved checklist
    artifacts = ROOT / '.workspace' / '.artifacts' / '.checklists'
    artifacts.mkdir(parents=True, exist_ok=True)
    log = artifacts / 'migration.log'
    with log.open('w', encoding='utf-8') as f:
        f.write('Planned schema updates (dry_run=%s):\n' % dry_run)
        for k, v in schema_versions.items():
            f.write(f"{k}: {v}\n")
        f.write('\nPlanned file modifications:\n')
        for p, old, new in planned_changes:
            f.write(f"{p}\n")
        f.write('\nUnresolved tokens:\n')
        for t in sorted(set(unresolved_tokens)):
            f.write(f"{t}\n")

    checklist = artifacts / 'migration-unresolved.list'
    if unresolved_tokens and not dry_run:
        with checklist.open('w', encoding='utf-8') as f:
            for t in sorted(set(unresolved_tokens)):
                f.write(f"{t}\n")

    if dry_run:
        # also write a dry-run checklist/log for inspection
        drylog = artifacts / 'migration-dryrun.log'
        with drylog.open('w', encoding='utf-8') as f:
            f.write('DRY RUN - planned changes:\n')
            for p, old, new in planned_changes:
                f.write(f"{p}\n")
            f.write('\nUnresolved tokens:\n')
            for t in sorted(set(unresolved_tokens)):
                f.write(f"{t}\n")

    print('Migration complete (dry_run=%s).' % dry_run)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description='Convert short names to UDIs (migration)')
    parser.add_argument('--dry-run', action='store_true', help='Do not write files; show planned changes')
    args = parser.parse_args()
    main(dry_run=args.dry_run)
